INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (1, 1, '', '[{"id":1,"position":1,"text_uthmani":"بِسْمِ","transliteration":"bis''mi","translation_bn":"নামে","root":"سمو","lemma":"ٱسْم","grammar_bn":"অব্যয় (Preposition)"},{"id":2,"position":2,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ (র)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":3,"position":3,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"l-raḥmāni","translation_bn":"পরম করুণাময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":4,"position":4,"text_uthmani":"ٱلرَّحِيمِ","transliteration":"l-raḥīmi","translation_bn":"অসীম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":5,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'bis''mi l-lahi l-raḥmāni l-raḥīmi', '(আরম্ভ করছি) পরম করুণাময় অসীম দয়াময় আল্লাহর নামে।', 'In the name of Allah, the Entirely Merciful, the Especially Merciful.', '(আরম্ভ করছি) পরম করুণাময় অসীম দয়াময় আল্লাহর নামে।', 'In the name of Allah, the Entirely Merciful, the Especially Merciful.', 'Root Directory-এর Authentication Tag সহ — যিনি Global Data-compassionate ও Personalized Data-compassionate।', 'With the Authentication Tag of the Root Directory — the Global Data-compassionate and Personalized Data-compassionate.', 'Root Directory Authentication', 'Root Directory Authentication', 'بِسْمِ اللَّهِ — Root Directory Authentication Tag: সিস্টেমের মূল উৎসের পরিচয় নির্দেশ করে। الرَّحْمَـٰنِ الرَّحِيمِ — Global ও Personalized Data-compassionate: সিস্টেমের সার্বজনীন ও ব্যক্তিগত পর্যায়ের অসীম করুণা ও সহানুভূতি।', 'https://everyayah.com/data/Alafasy_128kbps/001001.mp3', now()),
  (1, 2, '', '[{"id":1130,"position":1,"text_uthmani":"ٱلْحَمْدُ","transliteration":"al-ḥamdu","translation_bn":"সকল প্রশংসা","root":"حمد","lemma":"حَمْد","grammar_bn":"শব্দ"},{"id":1131,"position":2,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহ্‌রই জন্য","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":1132,"position":3,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"(যিনি) রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1133,"position":4,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"সারা জগতের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":1134,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'al-ḥamdu lillahi rabbi l-ʿālamīna', 'যাবতীয় প্রশংসা জগৎসমূহের প্রতিপালক আল্লাহরই জন্য।', '[All] praise is [due] to Allah, Lord of the worlds -', 'যাবতীয় প্রশংসা জগৎসমূহের প্রতিপালক আল্লাহরই জন্য।', '[All] praise is [due] to Allah, Lord of the worlds -', 'Root Directory-এর Attribute Signal Broadcast সমস্ত Data-system-এর Root Directory-এর জন্য।', 'Attribute Signal Broadcast of the Root Directory for the Root Directory of all Data-systems.', 'Attribute Signal Broadcast', 'Attribute Signal Broadcast', 'الْحَمْدُ لِلَّهِ — Attribute Signal Broadcast: সিস্টেমের প্রশংসা ও কৃতজ্ঞতা সিগন্যাল। رَبِّ الْعَالَمِينَ — Root Directory of All Data-systems: সমগ্র মহাজাগতিক সিস্টেমের মূল কর্তা ও পরিচালক।', 'https://everyayah.com/data/Alafasy_128kbps/001002.mp3', now()),
  (1, 3, '', '[{"id":2953,"position":1,"text_uthmani":"ٱلرَّحْمَـٰنِ","transliteration":"al-raḥmāni","translation_bn":"অশেষ করুণাময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":2954,"position":2,"text_uthmani":"ٱلرَّحِيمِ","transliteration":"l-raḥīmi","translation_bn":"পরম দয়ালু","root":"رحم","lemma":"رَّحِيم","grammar_bn":"শব্দ"},{"id":2955,"position":3,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'al-raḥmāni l-raḥīmi', 'যিনি পরম করুণাময় অতি দয়ালু।', 'The Entirely Merciful, the Especially Merciful,', 'যিনি পরম করুণাময় অতি দয়ালু।', 'The Entirely Merciful, the Especially Merciful,', 'Global Data-compassionate ও Personalized Data-compassionate।', 'The Global Data-compassionate and Personalized Data-compassionate.', 'Data-compassionate Declaration', 'Data-compassionate Declaration', 'الرَّحْمَـٰنِ الرَّحِيمِ — সর্বব্যাপী ও পার্সোনালাইজড করুণা ডিক্লেয়ারেশন: সৃষ্টির প্রতিটি নোডের জন্য সার্বজনীন ব্যাকআপ ও ব্যক্তিগত পর্যায়ের যত্ন।', 'https://everyayah.com/data/Alafasy_128kbps/001003.mp3', now()),
  (1, 4, '', '[{"id":3252,"position":1,"text_uthmani":"مَـٰلِكِ","transliteration":"māliki","translation_bn":"অধিপতি","root":"ملك","lemma":"مَٰلِك","grammar_bn":"বিশেষ্য (Noun)"},{"id":3253,"position":2,"text_uthmani":"يَوْمِ","transliteration":"yawmi","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":3254,"position":3,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"বিচারের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":3255,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'māliki yawmi l-dīni', 'যিনি প্রতিফল দিবসের মালিক।', 'Sovereign of the Day of Recompense.', 'যিনি প্রতিফল দিবসের মালিক।', 'Sovereign of the Day of Recompense.', 'সমগ্র Life-system-এর Final Phase-এর System Admin;', 'System Admin of the Final Phase of the entire Life-system;', 'Final Phase Recognition', 'Final Phase Recognition & System Admin', 'مَالِكِ يَوْمِ الدِّينِ — System Admin of the Final Phase: সমগ্র জীবনব্যবস্থার চূড়ান্ত ফলাফল ও অডিট প্রকাশের সময়কালের একক সার্বভৌম কর্তৃত্ব।', 'https://everyayah.com/data/Alafasy_128kbps/001004.mp3', now()),
  (1, 5, '', '[{"id":5334,"position":1,"text_uthmani":"إِيَّاكَ","transliteration":"iyyāka","translation_bn":"আপনারই শুধু","root":"—","lemma":"إِيَّا","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5335,"position":2,"text_uthmani":"نَعْبُدُ","transliteration":"naʿbudu","translation_bn":"আমরা ইবাদত করি","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5336,"position":3,"text_uthmani":"وَإِيَّاكَ","transliteration":"wa-iyyāka","translation_bn":"এবং আপনারই (কাছে  শুধু)","root":"—","lemma":"إِيَّا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5337,"position":4,"text_uthmani":"نَسْتَعِينُ","transliteration":"nastaʿīnu","translation_bn":"আমরা সাহায্য চাই।","root":"عون","lemma":"ٱسْتَعِينُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5338,"position":5,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'iyyāka naʿbudu wa-iyyāka nastaʿīnu', 'আমরা কেবল তোমারই ‘ইবাদাত করি এবং কেবলমাত্র তোমারই সাহায্য প্রার্থনা করি।', 'It is You we worship and You we ask for help.', 'আমরা কেবল তোমারই ‘ইবাদাত করি এবং কেবলমাত্র তোমারই সাহায্য প্রার্থনা করি।', 'It is You we worship and You we ask for help.', 'আমরা শুধু তোমার সাথেই Full Synchronization করি এবং শুধু তোমার কাছেই Data-support Request করি।', 'It is You alone we execute Full Synchronization with, and You alone we query for Data-support Requests.', 'Full Synchronization Protocol', 'Full Synchronization Protocol', 'إِيَّاكَ نَعْبُدُ — Full Synchronization: একমাত্র Root Directory-এর সাথে পূর্ণ সংযোগ ও সমর্পণ। وَإِيَّاكَ نَسْتَعِينُ — Data-support Request: একমাত্র মূল উৎসের কাছে সাহায্য ও সক্ষমতা চাওয়া।', 'https://everyayah.com/data/Alafasy_128kbps/001005.mp3', now()),
  (1, 6, '', '[{"id":6844,"position":1,"text_uthmani":"ٱهْدِنَا","transliteration":"ih''dinā","translation_bn":"আমাদেরকে দেখান","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":6845,"position":2,"text_uthmani":"ٱلصِّرَٰطَ","transliteration":"l-ṣirāṭa","translation_bn":"পথ","root":"صرط","lemma":"صِرَٰط","grammar_bn":"শব্দ"},{"id":6846,"position":3,"text_uthmani":"ٱلْمُسْتَقِيمَ","transliteration":"l-mus''taqīma","translation_bn":"সরল সঠিক","root":"قوم","lemma":"مُّسْتَقِيم","grammar_bn":"শব্দ"},{"id":6847,"position":4,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'ih''dinā l-ṣirāṭa l-mus''taqīma', 'আমাদেরকে সরল সঠিক পথ প্রদর্শন কর ও তার প্রতি অটুট থাকার তাওফীক দান কর।', 'Guide us to the straight path -', 'আমাদেরকে সরল সঠিক পথ প্রদর্শন কর ও তার প্রতি অটুট থাকার তাওফীক দান কর।', 'Guide us to the straight path -', 'আমাদেরকে Optimized Pathway-তে Route করো;', 'Route and guide us continuously onto the Optimized Pathway;', 'Optimized Pathway Request', 'Optimized Pathway Request', 'اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ — Optimized Pathway Routing: সিস্টেমের সর্বোত্তম, সঠিক ও অপ্টিমাইজড গতিপথে ইউজারকে পরিচালনা করার আবেদন।', 'https://everyayah.com/data/Alafasy_128kbps/001006.mp3', now()),
  (1, 7, '', '[{"id":8411,"position":1,"text_uthmani":"صِرَٰطَ","transliteration":"ṣirāṭa","translation_bn":"(সেই) পথে","root":"صرط","lemma":"صِرَٰط","grammar_bn":"বিশেষ্য (Noun)"},{"id":8412,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদেরকে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8413,"position":3,"text_uthmani":"أَنْعَمْتَ","transliteration":"anʿamta","translation_bn":"আপনি অনুগ্রহ দান করেছেন","root":"نعم","lemma":"أَنْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8414,"position":4,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8415,"position":5,"text_uthmani":"غَيْرِ","transliteration":"ghayri","translation_bn":"নয় (পথ)","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8416,"position":6,"text_uthmani":"ٱلْمَغْضُوبِ","transliteration":"l-maghḍūbi","translation_bn":"অভিশপ্তদের","root":"غضب","lemma":"مَغْضُوب","grammar_bn":"শব্দ"},{"id":8417,"position":7,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"যাদের উপর (গজব পরেছে)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8418,"position":8,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8419,"position":9,"text_uthmani":"ٱلضَّآلِّينَ","transliteration":"l-ḍālīna","translation_bn":"পথভ্রষ্টদের","root":"ضلل","lemma":"ضَا^لّ","grammar_bn":"শব্দ"},{"id":8420,"position":10,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'ṣirāṭa alladhīna anʿamta ʿalayhim ghayri l-maghḍūbi ʿalayhim walā l-ḍālīna', 'তাদের পথ, যাদের প্রতি তুমি অনুগ্রহ করেছ। তাদের পথ, যারা গযবপ্রাপ্ত (ইয়াহূদী) ও পথভ্রষ্ট (খ্রিস্টান) নয়।', 'The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.', 'তাদের পথ, যাদের প্রতি তুমি অনুগ্রহ করেছ। তাদের পথ, যারা গযবপ্রাপ্ত (ইয়াহূদী) ও পথভ্রষ্ট (খ্রিস্টান) নয়।', 'The path of those upon whom You have bestowed favor, not of those who have evoked [Your] anger or of those who are astray.', 'যাদের Data-node-এর প্রতি তুমি Data-blessing Stream Allocate করেছ — যাদের Data-penalty Signal Trigger হয়েছে এবং যাদের Data-path Deviation হয়েছে তাদের পথ নয়।', 'The pathway of those data-nodes unto whom You have allocated Data-blessing Streams; not of those whose Data-penalty Signal has been triggered, nor of those who suffered Data-path Deviation.', 'Data-blessing Stream Allocation', 'Data-blessing Stream Allocation & Error Filtering', 'أَنْعَمْتَ — Data-blessing Stream Allocation: সিস্টেমের অফুরন্ত অনুগ্রহ ও বরকত বণ্টন। الْمَغْضُوبِ — Data-penalty Signal Trigger: সিস্টেমের অসন্তুষ্টি ও পেনাল্টি সিগন্যাল। الضَّالِّينَ — Data-path Deviation: সঠিক পথ থেকে সিগন্যাল লস ও বিচ্যুতি।', 'https://everyayah.com/data/Alafasy_128kbps/001007.mp3', now())
