INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (2, 1, '', '[{"id":11,"position":1,"text_uthmani":"الٓمٓ","transliteration":"alif-lam-meem","translation_bn":"আলিফ লা-ম মী-ম","root":"—","lemma":"الٓمٓ","grammar_bn":"শব্দ"},{"id":12,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alif-lam-meem', 'আলিফ, লাম, মীম।', 'Alif, Lam, Meem.', 'আলিফ, লাম, মীম।', 'Alif, Lam, Meem.', '(আলিফ-লাম-মীম) — এগুলো হলো মহাজাগতিক সোর্স কোডের এনকোড করা চূড়ান্ত আলফা-নিউমেরিক ডেটা ক্যারেক্টার বা সিগন্যাল (Encrypted Cosmic Codes), যা মানুষের সচেতন মস্তিস্কের ডিকোড করার ক্ষমতার ঊর্ধ্বের এক অনন্য ইন্টারফেস।', NULL, 'মহাজাগতিক সোর্স কোড ও এনকোডেড আলফা-নিউমেরিক সিগন্যাল', NULL, 'الٓمٓ — ডিভাইন এনক্রিপশন হেডার: মহাজাগতিক অপারেটিং সিস্টেমের মূল কম্পাইলার কি (Compiler Key) ও ইউনিক ক্রিপ্টোগ্রাফিক সিগনেচার।', 'https://everyayah.com/data/Alafasy_128kbps/002001.mp3', now()),
  (2, 2, '', '[{"id":1195,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"(এটা) সেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":1196,"position":2,"text_uthmani":"ٱلْكِتَـٰبُ","transliteration":"l-kitābu","translation_bn":"মহাগ্রন্থ (আল্লাহর)","root":"كتب","lemma":"كِتَٰب","grammar_bn":"শব্দ"},{"id":1197,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا","grammar_bn":"না-বোধক (Negative)"},{"id":1198,"position":4,"text_uthmani":"رَيْبَ ۛ","transliteration":"rayba","translation_bn":"কোনো সন্দেহ","root":"ريب","lemma":"رَيْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":1200,"position":5,"text_uthmani":"فِيهِ ۛ","transliteration":"fīhi","translation_bn":"তাঁরমধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1202,"position":6,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"সৎপথ নির্দেশ (হেদায়াত)","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":1203,"position":7,"text_uthmani":"لِّلْمُتَّقِينَ","transliteration":"lil''muttaqīna","translation_bn":"মুত্তাকীদের জন্য","root":"وقي","lemma":"مُتَّقِين","grammar_bn":"অব্যয় (Preposition)"},{"id":1204,"position":8,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika l-kitābu lā rayba fīhi hudan lil''muttaqīna', 'এটা ঐ (মহান) কিতাব যাতে কোন সন্দেহ নেই, মুত্তাকীদের জন্য পথ নির্দেশ।', 'This is the Book about which there is no doubt, a guidance for those conscious of Allah -', 'এটা ঐ (মহান) কিতাব যাতে কোন সন্দেহ নেই, মুত্তাকীদের জন্য পথ নির্দেশ।', 'This is the Book about which there is no doubt, a guidance for those conscious of Allah -', 'এই হলো সেই অবিনশ্বর মহাজাগতিক মাস্টার ডেটাবেজ ও সোর্স কোড (আল-কিতাব) — যার অভ্যন্তরীণ ইনফরমেশন আর্কিটেকচারে কোনো এরর (Error), অসঙ্গতি বা দ্বিধার অবকাশ নেই; এটি মূলত সেইসব সচেতন সত্তার জন্য একটি চূড়ান্ত ফাংশনাল গাইডবুক (Guidance) — যারা সিস্টেমের নিয়ম মেনে নিজেদের বিপর্যয় ও এন্ট্রপি থেকে রক্ষা করতে চায় (Al-Muttaqin);', NULL, 'মহাজাগতিক মাস্টার ডেটাবেজ ও সিস্টেম অপ্টিমাইজেশন গাইডবুক', NULL, 'হুদাল্লিল মুত্তাকীন (هُدًى لِّلْمُتَّقِينَ - সিস্টেম অপ্টিমাইজেশন): ''তাকওয়া'' শব্দের বৈজ্ঞানিক অর্থ হলো এমন এক সতর্ক লাইফস্টাইল, যা সিস্টেমের ভেতর কোনো ক্রাশ বা এন্ট্রপি তৈরি করে না। এই কিতাব কেবল তাদের লাইফ ট্র্যাকিংয়ে কাজ করে, যারা নিজেদের ধ্বংস থেকে বাঁচাতে চায়।', 'https://everyayah.com/data/Alafasy_128kbps/002002.mp3', now()),
  (2, 3, '', '[{"id":2630,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2631,"position":2,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2632,"position":3,"text_uthmani":"بِٱلْغَيْبِ","transliteration":"bil-ghaybi","translation_bn":"অদৃশ্যের ওপর","root":"غيب","lemma":"غَيْب","grammar_bn":"অব্যয় (Preposition)"},{"id":2633,"position":4,"text_uthmani":"وَيُقِيمُونَ","transliteration":"wayuqīmūna","translation_bn":"এবং প্রতিষ্ঠিত করে","root":"قوم","lemma":"أَقَامَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2634,"position":5,"text_uthmani":"ٱلصَّلَوٰةَ","transliteration":"l-ṣalata","translation_bn":"সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"শব্দ"},{"id":2635,"position":6,"text_uthmani":"وَمِمَّا","transliteration":"wamimmā","translation_bn":"ও তা হতে যা","root":"—","lemma":"مِن\r","grammar_bn":"শব্দ"},{"id":2636,"position":7,"text_uthmani":"رَزَقْنَـٰهُمْ","transliteration":"razaqnāhum","translation_bn":"তাদের আমরা জীবিকা দিয়েছি","root":"رزق","lemma":"رَزَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2637,"position":8,"text_uthmani":"يُنفِقُونَ","transliteration":"yunfiqūna","translation_bn":"তারা ব্যয় করে","root":"نفق","lemma":"أَنفَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2638,"position":9,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna yu''minūna bil-ghaybi wayuqīmūna l-ṣalata wamimmā razaqnāhum yunfiqūna', 'যারা গায়বের প্রতি ঈমান আনে, নামায কায়িম করে এবং আমি যে জীবনোপকরণ তাদেরকে দিয়েছি তা থেকে তারা ব্যয় করে।', 'Who believe in the unseen, establish prayer, and spend out of what We have provided for them,', 'যারা গায়বের প্রতি ঈমান আনে, নামায কায়িম করে এবং আমি যে জীবনোপকরণ তাদেরকে দিয়েছি তা থেকে তারা ব্যয় করে।', 'Who believe in the unseen, establish prayer, and spend out of what We have provided for them,', 'যারা দৃশ্যমান জগতের বাইরের অদৃশ্য কোয়ান্টাম ডাইমেনশন, পরম উৎস এবং অপ্রকাশিত সত্যের ডেটাকে (Al-Ghaib) প্রমাণ ও যুক্তি সাপেক্ষে নিখুঁতভাবে এক্সেপ্ট করে (Aamanu), মহাজাগতিক সোর্সের সাথে নিয়মিতভাবে তাদের চেতনার ডেটা-কানেকশন ও ফ্রিকোয়েন্সি রি-ক্যালিব্রেশন প্রসেস (সালাত) সচল রাখে এবং আমি তাদেরকে যে শক্তি, জ্ঞান ও বস্তুগত রিসোর্স (Rizq) সরবরাহ করেছি — তা থেকে সিস্টেমে উন্মুক্ত প্রবাহ বা ডিস্ট্রিবিউশন (Spending/Circulation) নিশ্চিত করে;', NULL, 'কোয়ান্টাম রিয়্যালিটি, ফ্রিকোয়েন্সি ক্যালিব্রেশন (সালাত) ও রিসোর্স ডিস্ট্রিবিউশন', NULL, 'ইউ''মিনুনা বিল গাইব (يُؤْمِنُونَ بِالْغَيْبِ - কোয়ান্টাম রিয়্যালিটি): প্রথাগত অন্ধ বিশ্বাস নয়। ডার্ক ম্যাটার, গ্রাভিটি কিংবা সাব-অ্যাটমিক কণা আমরা সরাসরি চোখে দেখি না, কিন্তু তাদের গাণিতিক প্রমাণ ও প্রভাব দেখে তাদের অস্তিত্ব স্বীকার করি। ''গাইব'' হলো সেই অদৃশ্য ফান্ডামেন্টাল রিয়্যালিটি।', 'https://everyayah.com/data/Alafasy_128kbps/002003.mp3', now()),
  (2, 4, '', '[{"id":4246,"position":1,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"এবং যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4247,"position":2,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"বিশ্বাস করে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4248,"position":3,"text_uthmani":"بِمَآ","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4249,"position":4,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ করা হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4250,"position":5,"text_uthmani":"إِلَيْكَ","transliteration":"ilayka","translation_bn":"তোমার প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4251,"position":6,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4252,"position":7,"text_uthmani":"أُنزِلَ","transliteration":"unzila","translation_bn":"অবতীর্ণ করা হয়েছে","root":"نزل","lemma":"أَنزَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4253,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4254,"position":9,"text_uthmani":"قَبْلِكَ","transliteration":"qablika","translation_bn":"তোমার পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4255,"position":10,"text_uthmani":"وَبِٱلْـَٔاخِرَةِ","transliteration":"wabil-ākhirati","translation_bn":"এবং আখিরাতের উপর","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":4256,"position":11,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":4257,"position":12,"text_uthmani":"يُوقِنُونَ","transliteration":"yūqinūna","translation_bn":"দৃঢ়বিশ্বাস রাখে","root":"يقن","lemma":"يُوقِنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4258,"position":13,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhīna yu''minūna bimā unzila ilayka wamā unzila min qablika wabil-ākhirati hum yūqinūna', 'আর তোমার প্রতি যা নাযিল হয়েছে ও তোমার পূর্বে যা নাযিল হয়েছে তাতে তারা বিশ্বাস স্থাপন করে এবং পরকালের প্রতিও তারা নিশ্চিত বিশ্বাসী।', 'And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith].', 'আর তোমার প্রতি যা নাযিল হয়েছে ও তোমার পূর্বে যা নাযিল হয়েছে তাতে তারা বিশ্বাস স্থাপন করে এবং পরকালের প্রতিও তারা নিশ্চিত বিশ্বাসী।', 'And who believe in what has been revealed to you, [O Muhammad], and what was revealed before you, and of the Hereafter they are certain [in faith].', 'এবং যারা বর্তমান টাইম-ফ্রেমে তোমার কাছে ডাউনলিংক বা ডিকোড করা চূড়ান্ত সিস্টেম ডিরেক্টিভসের (The Decoded Manual / Quran) ওপর আস্থা রাখে এবং তোমার পূর্ববর্তী বিবর্তনীয় টাইম-লাইনে প্রেরিত সমস্ত আদি সোর্স ডাটার ওপর পূর্ণ আস্থা স্থাপন করে এবং সিস্টেমের চূড়ান্ত আউটপুট ফেজ, এন্ট্রপি হিসাব এবং কসমিক ডাটা-রিসেট টাইম-লাইনের (Al-Akhirah) প্রতি সম্পূর্ণ গাণিতিক ও লজিক্যাল নিশ্চয়তা (Yaqeen) পোষণ করে।', NULL, 'টাইম-লাইন সোর্স ডাটা ও কসমিক ডাটা-রিসেট (আখিরাত) নিশ্চয়তা', NULL, 'بِمَآ أُنزِلَ إِلَيْكَ وَمَآ أُنزِلَ مِن قَبْلِكَ — ক্রস-টাইমলাইন ডাটা সিনক্রোনাইজেশন: অতীত ও বর্তমানের সকল ডিভাইন ডাউনলিংক এবং চূড়ান্ত অডিট স্টেটে (আখিরাত) অটল বিশ্বাস।', 'https://everyayah.com/data/Alafasy_128kbps/002004.mp3', now()),
  (2, 5, '', '[{"id":5544,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"তারাই (প্রতিষ্ঠিত)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":5545,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5546,"position":3,"text_uthmani":"هُدًۭى","transliteration":"hudan","translation_bn":"সত্যপথের","root":"هدي","lemma":"هُدًى","grammar_bn":"বিশেষ্য (Noun)"},{"id":5547,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5548,"position":5,"text_uthmani":"رَّبِّهِمْ ۖ","transliteration":"rabbihim","translation_bn":"তাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5550,"position":6,"text_uthmani":"وَأُو۟لَـٰٓئِكَ","transliteration":"wa-ulāika","translation_bn":"এবং তারাই (ঐসব লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5551,"position":7,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"যারা","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5552,"position":8,"text_uthmani":"ٱلْمُفْلِحُونَ","transliteration":"l-muf''liḥūna","translation_bn":"সফলকাম","root":"فلح","lemma":"مُفْلِحُون","grammar_bn":"শব্দ"},{"id":5553,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika ʿalā hudan min rabbihim wa-ulāika humu l-muf''liḥūna', 'তারাই তাদের প্রতিপালকের হিদায়াতের উপর প্রতিষ্ঠিত আছে, আর তারাই সফলকাম।', 'Those are upon [right] guidance from their Lord, and it is those who are the successful.', 'তারাই তাদের প্রতিপালকের হিদায়াতের উপর প্রতিষ্ঠিত আছে, আর তারাই সফলকাম।', 'Those are upon [right] guidance from their Lord, and it is those who are the successful.', 'তারাই মূলত তাদের সিস্টেম আর্কিটেক্ট বা প্রতিপালকের (রাব্ব) পক্ষ থেকে প্রেরিত লাইভ ডিরেকশন ও অপ্টিমাল ট্র্যাকে (Optimal Vector / Guidance) সচল আছে এবং এই সত্তাগুলোই মহাজাগতিক ইকোসিস্টেমে সর্বোচ্চ কার্যক্ষমতা, এন্ট্রপি-মুক্ত স্থিতি ও চূড়ান্ত সফল আউটপুট (System Optimization / Success) লাভ করবে।', NULL, 'লাইভ ডিরেকশন, অপ্টিমাল ট্র্যাক ও এন্ট্রপি-মুক্ত স্থিতি', NULL, 'أُو۟لَـٰٓئِكَ عَلَىٰ هُدًۭى مِّن رَّبِّهِمْ — অপ্টিমাইজড সিস্টেম এক্সিকিউশন ও সাকসেস স্টেট: সিস্টেম আর্কিটেক্টের গাইডেন্সে পরিচালিত হয়ে সার্বিক ডোমেইনে সর্বোচ্চ ভারসাম্য ও সফলতা অর্জন।', 'https://everyayah.com/data/Alafasy_128kbps/002005.mp3', now()),
  (2, 6, '', '[{"id":6905,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6906,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6907,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"অবিশ্বাস করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6908,"position":4,"text_uthmani":"سَوَآءٌ","transliteration":"sawāon","translation_bn":"সমান","root":"سوي","lemma":"سَوَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":6909,"position":5,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের জন্যে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6910,"position":6,"text_uthmani":"ءَأَنذَرْتَهُمْ","transliteration":"a-andhartahum","translation_bn":"তাদের তুমি সতর্ক কর কি","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"সমতাবাচক (Equalization)"},{"id":6911,"position":7,"text_uthmani":"أَمْ","transliteration":"am","translation_bn":"অথবা","root":"—","lemma":"أَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6912,"position":8,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":6913,"position":9,"text_uthmani":"تُنذِرْهُمْ","transliteration":"tundhir''hum","translation_bn":"সতর্ক কর তুমি তাদেরকে","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6914,"position":10,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":6915,"position":11,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"তারা ঈমান আনবে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6916,"position":12,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'inna alladhīna kafarū sawāon ʿalayhim a-andhartahum am lam tundhir''hum lā yu''minūna', 'নিশ্চয় যারা কুফরী করেছে তাদেরকে তুমি ভয় দেখাও আর না দেখাও উভয়টাই তাদের জন্য সমান, তারা ঈমান আনবে না।', 'Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe.', 'নিশ্চয় যারা কুফরী করেছে তাদেরকে তুমি ভয় দেখাও আর না দেখাও উভয়টাই তাদের জন্য সমান, তারা ঈমান আনবে না।', 'Indeed, those who disbelieve - it is all the same for them whether you warn them or do not warn them - they will not believe.', 'নিশ্চয়ই যারা তাদের স্বাধীন ইচ্ছা (Free-will) অপব্যবহার করে সিস্টেমের ডিফল্ট ট্রুথ কোডকে ব্লক বা রিজেক্ট (Al-Kafirun) করে দিয়েছে — তাদের কগনিটিভ প্রসেসরে সতর্কতামূলক ডেটা ইনপুট দেওয়া হোক কিংবা না দেওয়া হোক, ফলাফলের ম্যাট্রিক্সে তা সম্পূর্ণ সমান; তারা কখনোই এই নিরাপদ মহাজাগতিক নেটওয়ার্কে নিজেদের এনরোল বা রেজিস্টার্ড (Enroll/Accept) করবে না।', NULL, 'ফ্রি-উইল অপব্যবহার ও ট্রুথ কোড ব্লকিং (কুফর)', NULL, 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ سَوَآءٌ عَلَيْهِمْ — হার্ড-লকড রিজেকশন স্টেট: ইনপুট সিগন্যাল বা সতর্কবার্তা নির্বিশেষে যে নোডগুলো তাদের কগনিটিভ পোর্ট চিরতরে বন্ধ করে রেখেছে।', 'https://everyayah.com/data/Alafasy_128kbps/002006.mp3', now()),
  (2, 7, '', '[{"id":8309,"position":1,"text_uthmani":"خَتَمَ","transliteration":"khatama","translation_bn":"সিল মেরে দিয়েছেন","root":"ختم","lemma":"خَتَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8310,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8311,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8312,"position":4,"text_uthmani":"قُلُوبِهِمْ","transliteration":"qulūbihim","translation_bn":"তাদের অন্তরের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8313,"position":5,"text_uthmani":"وَعَلَىٰ","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8314,"position":6,"text_uthmani":"سَمْعِهِمْ ۖ","transliteration":"samʿihim","translation_bn":"তাদের শ্রবণশক্তির","root":"سمع","lemma":"سَمْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":8316,"position":7,"text_uthmani":"وَعَلَىٰٓ","transliteration":"waʿalā","translation_bn":"এবং উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"শব্দ"},{"id":8317,"position":8,"text_uthmani":"أَبْصَـٰرِهِمْ","transliteration":"abṣārihim","translation_bn":"তাদের দৃষ্টিশক্তির","root":"بصر","lemma":"بَصَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":8318,"position":9,"text_uthmani":"غِشَـٰوَةٌۭ ۖ","transliteration":"ghishāwatun","translation_bn":"আবরণ (দিয়েছেন)","root":"غشو","lemma":"غِشَٰوَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8320,"position":10,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"এবং তাদেরজন্যে (রয়েছে)","root":"—","lemma":"وَلَهُمْ","grammar_bn":"শব্দ"},{"id":8321,"position":11,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8322,"position":12,"text_uthmani":"عَظِيمٌۭ","transliteration":"ʿaẓīmun","translation_bn":"কঠিন","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":8323,"position":13,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'khatama l-lahu ʿalā qulūbihim waʿalā samʿihim waʿalā abṣārihim ghishāwatun walahum ʿadhābun ʿaẓīmun', 'আল্লাহ তাদের অন্তর ও কানের উপর মোহর করে দিয়েছেন, আর তাদের চোখে আছে আবরণ আর তাদের জন্য আছে মহা শাস্তি।', 'Allah has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment.', 'আল্লাহ তাদের অন্তর ও কানের উপর মোহর করে দিয়েছেন, আর তাদের চোখে আছে আবরণ আর তাদের জন্য আছে মহা শাস্তি।', 'Allah has set a seal upon their hearts and upon their hearing, and over their vision is a veil. And for them is a great punishment.', 'যেহেতু তারা ক্রমাগত সত্যের সিগন্যাল রিজেক্ট করেছে, তাই মহাজাগতিক নিয়মের ডিফল্ট কোড (আল্লাহ) দ্বারাই তাদের মূল চিন্তা প্রসেসিং সেন্টার (কালব) এবং তাদের অডিও ইনপুট ডিভাইসের (শ্রবণেন্দ্রিয়) ওপর একটি পার্মানেন্ট ''রাইট-প্রটেক্টেড বা ডেটা-লক'' (Write-Protected / Seal) পড়ে গেছে; এবং তাদের ভিজ্যুয়াল সেন্সরের (দর্শনেন্দ্রিয়) ওপর তৈরি হয়েছে এক বিশাল তথ্যগত ফিল্টার বা কগনিটিভ অন্ধত্ব (Cognitive Blindness); আর তাদের এই সিস্টেমিক বিচ্যুতির জন্য নির্ধারিত রয়েছে এক সুদীর্ঘ ও তীব্র এনার্জি-ডিসরপশন বা চরম অশান্তির প্রতিক্রিয়া (Systemic Friction/Destruction)।', NULL, 'নিউরোপ্লাস্টিসিটি-ড্রিভেন কগনিটিভ লক ও ডেটা-ব্লকিং', NULL, 'খাতামাল্লাহু (خَتَمَ اللَّهُ - হার্ডওয়্যার ডেটা-লক): ৭ নম্বর আয়াতে একটি গভীর নিউরোসায়েন্টিফিক মেকানিজম রয়েছে। মানুষ যখন দীর্ঘ সময় ধরে কোনো পজিটিভ ডাটা বা সত্যকে রিজেক্ট করে, তখন তার মস্তিষ্কের নিউরাল পাথওয়েগুলো (Neural Pathways) স্থায়ীভাবে পরিবর্তিত হয়ে যায়। একে বিজ্ঞানের ভাষায় বলে Neuroplasticity-driven Cognitive Lock। আল্লাহ জবরদস্তি করে লক মারেননি, বরং আল্লাহর তৈরি নিউরো-বায়োলজিক্যাল আইনের ডিফল্ট মেকানিজমেই তাদের ব্রেন সত্যের ফ্রিকোয়েন্সি রিসিভ করার ক্ষমতা চিরতরে হারিয়ে ফেলে।', 'https://everyayah.com/data/Alafasy_128kbps/002007.mp3', now()),
  (2, 8, '', '[{"id":9598,"position":1,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"এবং মধ্যহতে","root":"—","lemma":"مِن\r","grammar_bn":"শব্দ"},{"id":9599,"position":2,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"মানুষের (এমনও আছে)","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":9600,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যারা","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9601,"position":4,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9602,"position":5,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"''''আমরা ঈমান এনেছি","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9603,"position":6,"text_uthmani":"بِٱللَّهِ","transliteration":"bil-lahi","translation_bn":"আল্লাহর উপর","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":9604,"position":7,"text_uthmani":"وَبِٱلْيَوْمِ","transliteration":"wabil-yawmi","translation_bn":"ও দিনের উপর","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9605,"position":8,"text_uthmani":"ٱلْـَٔاخِرِ","transliteration":"l-ākhiri","translation_bn":"আখিরাতের''''","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":9606,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"অথচ না","root":"—","lemma":"مَا","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":9607,"position":10,"text_uthmani":"هُم","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُم","grammar_bn":"সর্বনাম (Pronoun)"},{"id":9608,"position":11,"text_uthmani":"بِمُؤْمِنِينَ","transliteration":"bimu''minīna","translation_bn":"মুমিন","root":"امن","lemma":"مُؤْمِن","grammar_bn":"অব্যয় (Preposition)"},{"id":9609,"position":12,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wamina l-nāsi man yaqūlu āmannā bil-lahi wabil-yawmi l-ākhiri wamā hum bimu''minīna', 'মানুষের মধ্যে এমন লোক আছে যারা বলে, ‘‘আমরা আল্লাহর প্রতি এবং আখেরাতের দিনের প্রতি ঈমান এনেছি’’ কিন্তু প্রকৃতপক্ষে তারা মু’মিন নয়।', 'And of the people are some who say, "We believe in Allah and the Last Day," but they are not believers.', 'মানুষের মধ্যে এমন লোক আছে যারা বলে, ‘‘আমরা আল্লাহর প্রতি এবং আখেরাতের দিনের প্রতি ঈমান এনেছি’’ কিন্তু প্রকৃতপক্ষে তারা মু’মিন নয়।', 'And of the people are some who say, "We believe in Allah and the Last Day," but they are not believers.', 'এবং কার্বন-ভিত্তিক এই মানবজাতির (নাস) মধ্যে এমন কিছু ছদ্মবেশী ইউজার বা নোড রয়েছে যারা মুখে দাবি করে—‘আমরা পরম উৎস কোড (আল্লাহ) এবং সিস্টেমের চূড়ান্ত ডাটা-রিসেট টাইম-লাইনের (আল-ইয়াওমিল আখির) সাথে এলাইনড বা রেজিস্টার্ড (আমানু) হয়েছি’; অথচ প্রকৃত ডাটা স্ট্রাকচারে তারা মোটেও সিস্টেম-ইন্টিগ্রেটেড বা সত্যের সাথে সিনক্রোনাইজড (মু''মিনিন) নয়।', NULL, 'ছদ্মবেশী ডামি ইউজার ও সিস্টেম ইন্টিগ্রেশন ফেইলিওর', NULL, 'مَن يَقُولُ ءَامَنَّا بِٱللَّهِ وَمَا هُم بِمُؤْمِنِينَ — সিউডো-ইন্টিগ্রেশন ও ফলস সিগন্যালিং: ওওএসের ফ্রন্ট-এন্ডে ভেরিফায়েড দাবি করলেও ব্যাক-এন্ড কোডে জিরো-অ্যালাইনমেন্ট।', 'https://everyayah.com/data/Alafasy_128kbps/002008.mp3', now()),
  (2, 9, '', '[{"id":9694,"position":1,"text_uthmani":"يُخَـٰدِعُونَ","transliteration":"yukhādiʿūna","translation_bn":"তারা প্রতারিত করতে চায়","root":"خدع","lemma":"يُخَٰدِعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9695,"position":2,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহকে","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9696,"position":3,"text_uthmani":"وَٱلَّذِينَ","transliteration":"wa-alladhīna","translation_bn":"ও (তাদেরকে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9697,"position":4,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9698,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"কিন্তু না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":9699,"position":6,"text_uthmani":"يَخْدَعُونَ","transliteration":"yakhdaʿūna","translation_bn":"তারা প্রতারিত করে","root":"خدع","lemma":"يَخْدَعُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9700,"position":7,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":9701,"position":8,"text_uthmani":"أَنفُسَهُمْ","transliteration":"anfusahum","translation_bn":"তাদের নিজেদেরকে","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":9702,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":9703,"position":10,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"তারা অনুভব করে","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9704,"position":11,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'yukhādiʿūna l-laha wa-alladhīna āmanū wamā yakhdaʿūna illā anfusahum wamā yashʿurūna', 'তারা আল্লাহ ও মু’মিনদেরকে প্রতারিত করে, আসলে তারা নিজেদেরকে ছাড়া অন্য কাউকে প্রতারিত করে না, কিন্তু এটা তারা উপলব্ধি করতে পারে না।', 'They [think to] deceive Allah and those who believe, but they deceive not except themselves and perceive [it] not.', 'তারা আল্লাহ ও মু’মিনদেরকে প্রতারিত করে, আসলে তারা নিজেদেরকে ছাড়া অন্য কাউকে প্রতারিত করে না, কিন্তু এটা তারা উপলব্ধি করতে পারে না।', 'They [think to] deceive Allah and those who believe, but they deceive not except themselves and perceive [it] not.', 'তারা তাদের ত্রুটিপূর্ণ সিগন্যাল ও ডামি ডাটা দিয়ে পরম উৎস কোড (আল্লাহ) এবং প্রকৃত সিস্টেম-ইন্টিগ্রেটেড ইউজারদের (আমানু) সাথে ম্যানিপুলেশন বা হ্যাকিং (Spoofing/Deception) করতে চায়; অথচ তারা মূলত তাদের নিজস্ব সিস্টেমের ভেতরেই নেতিবাচক এন্ট্রপি ও সেলফ-ড্যামেজ (Self-Deception) তৈরি করছে, কিন্তু তাদের কগনিটিভ সেন্সরগুলো তা ডিটেক্ট বা অনুভব (যাশউরু) করতে পারছে না।', NULL, 'প্রোটোকল স্পুফিং ও স্বয়ংক্রিয় সেলফ-ড্যামেজ এন্ট্রপি', NULL, 'ইউখাদিউনাল্লাহ (يُخَادِعُونَ اللَّهَ - ডেটা স্পুফিং): আইটি এবং নেটওয়ার্ক সিকিউরিটির ভাষায় একে বলা হয় "IP Spoofing" বা "Data Mimicry"। মুনাফিকরা মূলত ডামি সিগন্যাল (Dummy Signals) পাঠায়, অর্থাৎ বাইরে থেকে নিজেকে লয়াল ইউজার দেখায় কিন্তু ব্যাক-এন্ডে তাদের ডাটাবেজ করাপ্টেড থাকে। তারা ভাবে তারা সিস্টেমকে ট্রিক করছে, কিন্তু মহাজাগতিক মাস্টার সার্ভারে প্রতিটি ডাটা-লগ রিয়েল টাইমে ট্র্যাকড হয়।', 'https://everyayah.com/data/Alafasy_128kbps/002009.mp3', now()),
  (2, 10, '', '[{"id":10915,"position":1,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10916,"position":2,"text_uthmani":"قُلُوبِهِم","transliteration":"qulūbihim","translation_bn":"তাদের অন্তর সমূহের","root":"قلب","lemma":"قَلْب","grammar_bn":"বিশেষ্য (Noun)"},{"id":10917,"position":3,"text_uthmani":"مَّرَضٌۭ","transliteration":"maraḍun","translation_bn":"রোগ (আছে)","root":"مرض","lemma":"مَّرَض","grammar_bn":"বিশেষ্য (Noun)"},{"id":10918,"position":4,"text_uthmani":"فَزَادَهُمُ","transliteration":"fazādahumu","translation_bn":"বৃদ্ধি করলেন তাই (আরও) তাদেরকে","root":"زيد","lemma":"زَادَ","grammar_bn":"শব্দ"},{"id":10919,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10920,"position":6,"text_uthmani":"مَرَضًۭا ۖ","transliteration":"maraḍan","translation_bn":"(তাদের) রোগ","root":"مرض","lemma":"مَّرَض","grammar_bn":"বিশেষ্য (Noun)"},{"id":10922,"position":7,"text_uthmani":"وَلَهُمْ","transliteration":"walahum","translation_bn":"এবং তাদের জন্য (রয়েছে)","root":"—","lemma":"وَلَهُمْ","grammar_bn":"শব্দ"},{"id":10923,"position":8,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":10924,"position":9,"text_uthmani":"أَلِيمٌۢ","transliteration":"alīmun","translation_bn":"কষ্টদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":10925,"position":10,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"এজন্যে যে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10926,"position":11,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10927,"position":12,"text_uthmani":"يَكْذِبُونَ","transliteration":"yakdhibūna","translation_bn":"তারা মিথ্যা বলতো","root":"كذب","lemma":"كَذَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10928,"position":13,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'fī qulūbihim maraḍun fazādahumu l-lahu maraḍan walahum ʿadhābun alīmun bimā kānū yakdhibūna', 'তাদের অন্তরে আছে ব্যাধি, অতঃপর আল্লাহ তাদের ব্যাধি বাড়িয়ে দিয়েছেন আর তাদের জন্য রয়েছে যন্ত্রণাদায়ক শাস্তি, কারণ তারা মিথ্যেবাদী।', 'In their hearts is disease, so Allah has increased their disease; and for them is a painful punishment because they [habitually] used to lie.', 'তাদের অন্তরে আছে ব্যাধি, অতঃপর আল্লাহ তাদের ব্যাধি বাড়িয়ে দিয়েছেন আর তাদের জন্য রয়েছে যন্ত্রণাদায়ক শাস্তি, কারণ তারা মিথ্যেবাদী।', 'In their hearts is disease, so Allah has increased their disease; and for them is a painful punishment because they [habitually] used to lie.', 'তাদের মূল চিন্তা প্রসেসিং সেন্টারে (কালব) একটি বড় ধরণের সিস্টেমিক এরর বা লজিক্যাল ম্যালওয়্যার (Marad) রয়ে গেছে; যার ফলে মহাজাগতিক নিয়মের ডিফল্ট কোড (আল্লাহ) অনুযায়ী তাদের সেই অভ্যন্তরীণ ত্রুটি বা এন্ট্রপির মাত্রা আরও বৃদ্ধি পায় (Feedback Loop of Error); আর তাদের এই ক্রমাগত ডাটা ফ্যাব্রিকেশন বা মিথ্যা ইনপুটের (যাকজিবুন) কারণে সিস্টেমে তৈরি হয় এক তীব্র মনস্তাত্ত্বিক ঘর্ষণ ও যন্ত্রণাদায়ক রি-অ্যাকশন (Systemic Friction/Painful Punishment)।', NULL, 'লজিক্যাল ম্যালওয়্যার ও পজিটিভ ফিডব্যাক এরর লুপ', NULL, 'ফাযাদাহুমুল্লাহু মারাযান (فَزَادَهُمُ اللَّهُ مَرَضًا - পজিটিভ ফিডব্যাক লুপ): সাইকোলজি এবং সিস্টেম ইঞ্জিনিয়ারিংয়ের একটি অদ্ভুত নিয়ম হলো—কেউ যখন নিজের ভুলকে জাস্টিফাই করে বারবার সিস্টেমে ভুল ডাটা দেয়, তখন সিস্টেম তার সেই এরর বা ''মারায''-কে লক করে দেয় এবং তা গুণিতক হারে বাড়তে থাকে। আল্লাহ কোনো পক্ষপাতিত্ব করে রোগ বাড়াননি, বরং এটি মনস্তাত্ত্বিক ডিফল্ট ফিডব্যাক লুপেরই একটি স্বয়ংক্রিয় পরিণতি।', 'https://everyayah.com/data/Alafasy_128kbps/002010.mp3', now()),
  (2, 11, '', '[{"id":12330,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":12331,"position":2,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"বলা হয়","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12332,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের উদ্দেশ্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":12333,"position":4,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"''''না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":12334,"position":5,"text_uthmani":"تُفْسِدُوا۟","transliteration":"tuf''sidū","translation_bn":"বিপর্যয় সৃষ্টি করো","root":"فسد","lemma":"أَفْسَدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12335,"position":6,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12336,"position":7,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"পৃথিবীর''''","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":12337,"position":8,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12338,"position":9,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"''''মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":12339,"position":10,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":12340,"position":11,"text_uthmani":"مُصْلِحُونَ","transliteration":"muṣ''liḥūna","translation_bn":"সংশোধনকারী''''","root":"صلح","lemma":"مُصْلِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":12341,"position":12,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā qīla lahum lā tuf''sidū fī l-arḍi qālū innamā naḥnu muṣ''liḥūna', 'তাদেরকে যখন বলা হয়, ‘পৃথিবীতে ফাসাদ সৃষ্টি করো না’; তারা বলে, ‘আমরা তো সংশোধনকারী’।', 'And when it is said to them, "Do not cause corruption on the earth," they say, "We are but reformers."', 'তাদেরকে যখন বলা হয়, ‘পৃথিবীতে ফাসাদ সৃষ্টি করো না’; তারা বলে, ‘আমরা তো সংশোধনকারী’।', 'And when it is said to them, "Do not cause corruption on the earth," they say, "We are but reformers."', 'এবং যখন এই গ্লোবাল ইকোসিস্টেমের ডেটা প্যারামিটারে তাদের সতর্ক করে বলা হয়—‘তোমরা এই পার্থিব বায়ো-স্ফিয়ার বা গ্রাউন্ড লেভেলে (আরদ্) কোনো ধরণের সিস্টেমিক বিশৃঙ্খলা, দূষণ বা নেতিবাচক এন্ট্রপি (ফাসাদ) তৈরি করো না’; তখন তারা তাদের কগনিটিভ বায়াস বা অহংকারবশত দাবি করে—‘নিশ্চয়ই আমরাই তো এই সিস্টেমের অপ্টিমাইজেশন ও প্রকৃত সংশোধনকারী (Muslihoon)!’', NULL, 'ইকোসিস্টেমিক বিশৃঙ্খলা ও অপ্টিমাইজেশনের মিথ্যা দাবি', NULL, 'লা তুফসিদু ফিল আরদ্ (لَا تُفْسِدُوا فِي الْأَرْضِ - সামাজিক ও পরিবেশগত এন্ট্রপি): ''ফাসাদ'' শব্দের বৈজ্ঞানিক প্রতিশব্দ হলো "Entropy বা বিশৃঙ্খলা"। যখন কোনো ডাবল-স্ট্যান্ডার্ড বা হিপোক্রিট গোষ্ঠী সমাজে ইনফরমেশন ম্যানিপুলেশন (মিথ্যা প্রোপাগান্ডা, সম্পদ কুক্ষিগত করা) শুরু করে, তখন পুরো সামাজিক ও ভৌগোলিক ইকোসিস্টেমের ভারসাম্য নষ্ট হয়ে যায়। সবচেয়ে বিপজ্জনক বিষয় হলো, তারা এই ধ্বংসাত্মক কাজকে প্রগতি বা ''সংশোধন'' (ইসলাহ) বলে প্রচার করে।', 'https://everyayah.com/data/Alafasy_128kbps/002011.mp3', now()),
  (2, 12, '', '[{"id":13812,"position":1,"text_uthmani":"أَلَآ","transliteration":"alā","translation_bn":"সাবধান","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":13813,"position":2,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"তারা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":13814,"position":3,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":13815,"position":4,"text_uthmani":"ٱلْمُفْسِدُونَ","transliteration":"l-muf''sidūna","translation_bn":"বিপর্যয় সৃষ্টিকারী","root":"فسد","lemma":"مُفْسِد","grammar_bn":"শব্দ"},{"id":13816,"position":5,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":13817,"position":6,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":13818,"position":7,"text_uthmani":"يَشْعُرُونَ","transliteration":"yashʿurūna","translation_bn":"তারা অনুভব করে","root":"شعر","lemma":"يَشْعُرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13819,"position":8,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'alā innahum humu l-muf''sidūna walākin lā yashʿurūna', 'মূলতঃ তারাই অশান্তি সৃষ্টিকারী, কিন্তু তারা তা বুঝতে পারে না।', 'Unquestionably, it is they who are the corrupters, but they perceive [it] not.', 'মূলতঃ তারাই অশান্তি সৃষ্টিকারী, কিন্তু তারা তা বুঝতে পারে না।', 'Unquestionably, it is they who are the corrupters, but they perceive [it] not.', 'লজিক্যালি জেনে রাখো! নিশ্চয়ই এই ছদ্মবেশী নোডগুলোই মূলত পুরো ইকোসিস্টেমে তীব্র বিশৃঙ্খলা ও ক্ষতিকারক ভাইরাসের (Mufsidoon) মূল সোর্স, কিন্তু তাদের কগনিটিভ প্রসেসর এতটাই নিষ্ক্রিয় যে তারা তা ডিটেক্ট বা রিলাইজ (যাশউরু) করতে পারে না।', NULL, 'ভাইরাস সোর্স ডিটেকশন ও কগনিটিভ নিষ্ক্রিয়তা', NULL, 'أَلَآ إِنَّهُمْ هُمُ ٱلْمُفْسِدُونَ وَلَـٰكِن لَّا يَشْعُرُونَ — অসচেতন সিস্টেমিক করাপশন: ওওএসে ড্যামেজ তৈরি করা সত্ত্বেও সেলফ-ডায়াগনস্টিক অক্ষমতার কারণে তা বুঝতে না পারা।', 'https://everyayah.com/data/Alafasy_128kbps/002012.mp3', now()),
  (2, 13, '', '[{"id":15180,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15181,"position":2,"text_uthmani":"قِيلَ","transliteration":"qīla","translation_bn":"বলা হয়","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15182,"position":3,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের উদ্দেশ্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":15183,"position":4,"text_uthmani":"ءَامِنُوا۟","transliteration":"āminū","translation_bn":"''''তোমরা ঈমান আনো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15184,"position":5,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15185,"position":6,"text_uthmani":"ءَامَنَ","transliteration":"āmana","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15186,"position":7,"text_uthmani":"ٱلنَّاسُ","transliteration":"l-nāsu","translation_bn":"মানুষ''''","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":15187,"position":8,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15188,"position":9,"text_uthmani":"أَنُؤْمِنُ","transliteration":"anu''minu","translation_bn":"''''আমরা কি ঈমান আনবো","root":"امن","lemma":"ءَامَنَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":15189,"position":10,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15190,"position":11,"text_uthmani":"ءَامَنَ","transliteration":"āmana","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15191,"position":12,"text_uthmani":"ٱلسُّفَهَآءُ ۗ","transliteration":"l-sufahāu","translation_bn":"বোকারা''''","root":"سفه","lemma":"سَفِيه","grammar_bn":"শব্দ"},{"id":15193,"position":13,"text_uthmani":"أَلَآ","transliteration":"alā","translation_bn":"সাবধান","root":"—","lemma":"أَلَا^\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":15194,"position":14,"text_uthmani":"إِنَّهُمْ","transliteration":"innahum","translation_bn":"নিশ্চয়ই তারা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":15195,"position":15,"text_uthmani":"هُمُ","transliteration":"humu","translation_bn":"তারাই","root":"—","lemma":"هُمُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":15196,"position":16,"text_uthmani":"ٱلسُّفَهَآءُ","transliteration":"l-sufahāu","translation_bn":"বোকা","root":"سفه","lemma":"سَفِيه","grammar_bn":"শব্দ"},{"id":15197,"position":17,"text_uthmani":"وَلَـٰكِن","transliteration":"walākin","translation_bn":"কিন্তু","root":"—","lemma":"لَٰكِن\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":15198,"position":18,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15199,"position":19,"text_uthmani":"يَعْلَمُونَ","transliteration":"yaʿlamūna","translation_bn":"তারা জানে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15200,"position":20,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā qīla lahum āminū kamā āmana l-nāsu qālū anu''minu kamā āmana l-sufahāu alā innahum humu l-sufahāu walākin lā yaʿlamūna', 'যখন তাদেরকে বলা হয়, যে সব লোক ঈমান এনেছে তাদের মতো তোমরাও ঈমান আন, তারা বলে, ‘নির্বোধেরা যেমন ঈমান এনেছে, আমরাও কি তেমনি ঈমান আনব’? আসলে তারাই নির্বোধ, কিন্তু তারা তা’ বুঝতে পারে না।', 'And when it is said to them, "Believe as the people have believed," they say, "Should we believe as the foolish have believed?" Unquestionably, it is they who are the foolish, but they know [it] not.', 'যখন তাদেরকে বলা হয়, যে সব লোক ঈমান এনেছে তাদের মতো তোমরাও ঈমান আন, তারা বলে, ‘নির্বোধেরা যেমন ঈমান এনেছে, আমরাও কি তেমনি ঈমান আনব’? আসলে তারাই নির্বোধ, কিন্তু তারা তা’ বুঝতে পারে না।', 'And when it is said to them, "Believe as the people have believed," they say, "Should we believe as the foolish have believed?" Unquestionably, it is they who are the foolish, but they know [it] not.', 'এবং যখন তাদের নির্দেশ দেওয়া হয়—‘তোমরাও ঠিক সেভাবেই খাঁটি প্রমাণের ভিত্তিতে সিস্টেমে এন্ট্রল হও (আমানু) যেভাবে অন্যান্য ডেটা-ভেরিফাইড ইউজাররা (নাস) সোর্সের সাথে যুক্ত হয়েছে’; তখন তারা অবজ্ঞার সাথে বলে—‘আমরা কি সেইসব ডেটা-অ্যানালিটিক্সহীন সাধারণ বা নির্বোধদের (Sufaha) মতো এই সিস্টেম কোড মেনে নেব?’ সাবধান! প্রকৃত ইনফরমেশন থিওরি অনুযায়ী ওরাই হলো মূলত ডেটা-শূন্য চরম নির্বোধ বা সিস্টেমের জন্য অকেজো এলিমেন্ট, কিন্তু তারা বস্তুনিষ্ঠভাবে এই চরম সত্যটি জানে না (লা ইয়া''লামুন)।', NULL, 'লো-কগনিটিভ নোড ও ডেটা-শূন্য চরম নির্বুদ্ধিতা', NULL, 'আস-সুফাহা (السُّفَهَاءُ - লো-কগনিটিভ নোড): এর বৈজ্ঞানিক অর্থ হলো এমন এক অবস্থা যেখানে ডাটা প্রসেস করার এবং সঠিক সিদ্ধান্ত নেওয়ার ক্ষমতা লোপ পায়। মুনাফিকরা নিজেদের অতিরিক্ত চালাক ও বুদ্ধিজীবী মনে করে এবং সাধারণ সত্যনিষ্ঠ মানুষদের ''নির্বোধ'' ভাবে। কিন্তু কুরআন লজিক্যালি প্রমাণ করছে যে—সোর্স কোডের বাইরে গিয়ে নিজস্ব ট্র্যাশ ডাটাবেজ নিয়ে অহংকার করাই হলো মহাজাগতিক পরিভাষায় সবচেয়ে বড় নির্বুদ্ধিতা।', 'https://everyayah.com/data/Alafasy_128kbps/002013.mp3', now()),
  (2, 14, '', '[{"id":16289,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16290,"position":2,"text_uthmani":"لَقُوا۟","transliteration":"laqū","translation_bn":"তারা মিলিত হয়","root":"لقي","lemma":"لَقُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16291,"position":3,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(তাদের সাথে) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16292,"position":4,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16293,"position":5,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16294,"position":6,"text_uthmani":"ءَامَنَّا","transliteration":"āmannā","translation_bn":"''''আমরা ঈমান এনেছি''''","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16295,"position":7,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16296,"position":8,"text_uthmani":"خَلَوْا۟","transliteration":"khalaw","translation_bn":"গোপনে মিলে","root":"خلو","lemma":"خَلَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":16297,"position":9,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"সাথে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16298,"position":10,"text_uthmani":"شَيَـٰطِينِهِمْ","transliteration":"shayāṭīnihim","translation_bn":"তাদের শয়তান (বন্ধুদের)","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":16299,"position":11,"text_uthmani":"قَالُوٓا۟","transliteration":"qālū","translation_bn":"তারা বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16300,"position":12,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"''''নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16301,"position":13,"text_uthmani":"مَعَكُمْ","transliteration":"maʿakum","translation_bn":"তোমাদের সাথে","root":"—","lemma":"مَع","grammar_bn":"স্থানবাচক (Location)"},{"id":16302,"position":14,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"মূলতঃ","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16303,"position":15,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":16304,"position":16,"text_uthmani":"مُسْتَهْزِءُونَ","transliteration":"mus''tahziūna","translation_bn":"উপহাসকারী (মু''মিনদের সাথে)''''","root":"هزا","lemma":"مُسْتَهْزِءُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":16305,"position":17,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā laqū alladhīna āmanū qālū āmannā wa-idhā khalaw ilā shayāṭīnihim qālū innā maʿakum innamā naḥnu mus''tahziūna', 'যখন তারা মু’মিনদের সংস্পর্শে আসে তখন বলে, ‘আমরা ঈমান এনেছি’; আর যখন তারা নিভৃতে তাদের শয়ত্বানদের (সর্দারদের) সঙ্গে মিলিত হয় তখন বলে, ‘আমরা তোমাদের সাথেই আছি, আমরা শুধু তাদের সঙ্গে ঠাট্টা-তামাশা করি মাত্র’।', 'And when they meet those who believe, they say, "We believe"; but when they are alone with their evil ones, they say, "Indeed, we are with you; we were only mockers."', 'যখন তারা মু’মিনদের সংস্পর্শে আসে তখন বলে, ‘আমরা ঈমান এনেছি’; আর যখন তারা নিভৃতে তাদের শয়ত্বানদের (সর্দারদের) সঙ্গে মিলিত হয় তখন বলে, ‘আমরা তোমাদের সাথেই আছি, আমরা শুধু তাদের সঙ্গে ঠাট্টা-তামাশা করি মাত্র’।', 'And when they meet those who believe, they say, "We believe"; but when they are alone with their evil ones, they say, "Indeed, we are with you; we were only mockers."', 'এবং যখন এই ছদ্মবেশী নোডগুলো প্রকৃত সিস্টেম-ইন্টিগ্রেটেড ইউজারদের (আমানু) নেটওয়ার্ক ইন্টারফেসে আসে, তখন ডামি সিগন্যাল দিয়ে বলে—‘আমরা তোমাদের ডাটাবেজ এক্সেপ্ট করেছি (আমানু)’; কিন্তু যখন তারা আইসোলেটেড হয়ে তাদের নিজস্ব ক্যাটাগরির তীব্র এন্ট্রপি-উৎপাদনকারী ও বিচ্যুত মূল হোতা বা ম্যালওয়্যার সোর্সদের (শায়াত্বীনিহিম) সাথে ব্যাক-চ্যানেল সংযোগ স্থাপন করে, তখন বলে—‘নিশ্চয়ই আমরা তোমাদের আর্কিটেকচার ও সিস্টেম কোডের সাথেই আছি, আমরা তো কেবল ওই পজিটিভ সিস্টেমের ইউজারদের সাথে প্রোটোকল স্পুফিং বা উপহাস (মুস্তাহজিউন) করছি’।', NULL, 'ম্যালওয়্যার সোর্সদের সাথে ব্যাক-চ্যানেল সংযোগ', NULL, 'শায়াত্বীন (شَيَاطِينِ - ম্যালওয়্যার আর্কিটেক্টস): ''শায়তান'' শব্দের বৈজ্ঞানিক অর্থ হলো এমন যেকোনো চরম বিচ্যুত, চরম এন্ট্রপি-যুক্ত বিদ্রোহী শক্তি (তা প্লাজমা-ভিত্তিক ইবলিসের দল হতে পারে, কিংবা হিউম্যান ম্যালওয়্যার হতে পারে) যারা মূল সার্ভারকে ধ্বংস করতে চায়। মুনাফিকরা যখন এদের সাথে ব্যাক-এন্ডে ডেটা শেয়ার করে, তখন তাদের সিস্টেমের ডাবল-স্ট্যান্ডার্ড চূড়ান্ত রূপ নেয়।', 'https://everyayah.com/data/Alafasy_128kbps/002014.mp3', now()),
  (2, 15, '', '[{"id":17494,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17495,"position":2,"text_uthmani":"يَسْتَهْزِئُ","transliteration":"yastahzi-u","translation_bn":"উপহাস করেন","root":"هزا","lemma":"ٱسْتُهْزِئَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17496,"position":3,"text_uthmani":"بِهِمْ","transliteration":"bihim","translation_bn":"তাদের সাথে","root":"—","lemma":"بِهِمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":17497,"position":4,"text_uthmani":"وَيَمُدُّهُمْ","transliteration":"wayamudduhum","translation_bn":"এবং তাদের ঢিলদেন","root":"مدد","lemma":"مَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17498,"position":5,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17499,"position":6,"text_uthmani":"طُغْيَـٰنِهِمْ","transliteration":"ṭugh''yānihim","translation_bn":"তাদের অবাধ্যতার","root":"طغي","lemma":"طُغْيَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":17500,"position":7,"text_uthmani":"يَعْمَهُونَ","transliteration":"yaʿmahūna","translation_bn":"তারা উদভ্রান্ত হয়ে ফিরে","root":"عمه","lemma":"يَعْمَهُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17501,"position":8,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu yastahzi-u bihim wayamudduhum fī ṭugh''yānihim yaʿmahūna', 'আল্লাহ তাদের সঙ্গে (জবাবে) উপহাস করেন এবং তাদের অবাধ্যতায় বিভ্রান্তের মত তাদেরকে ঘুরে মরার অবকাশ দেন।', '[But] Allah mocks them and prolongs them in their transgression [while] they wander blindly.', 'আল্লাহ তাদের সঙ্গে (জবাবে) উপহাস করেন এবং তাদের অবাধ্যতায় বিভ্রান্তের মত তাদেরকে ঘুরে মরার অবকাশ দেন।', '[But] Allah mocks them and prolongs them in their transgression [while] they wander blindly.', 'মহাজাগতিক সোর্স কোডের ডিফল্ট নিয়মে (আল্লাহ) তাদের এই প্রতারণামূলক সিগন্যালকে কাউন্টার-লুপে ফেলে দেওয়া হয় (সিস্টেমিক রিজেকশন) এবং তাদের নিজস্ব তৈরি করা ডাটা-বিচ্যুতি ও তীব্র সিস্টেমিক এন্ট্রপির (তুগইয়ান) ভেতরেই তাদের মুক্ত ফ্রি-উইলকে অপ্টিমাইজড হতে দেওয়া হয়—যার ফলে তারা এক স্থায়ী কগনিটিভ অন্ধত্ব ও দিকভ্রান্ত চক্রের (যামাহুন) মধ্যে হাবুডুবু খেতে থাকে।', NULL, 'কাউন্টার-লুপে সিস্টেমিক রিজেকশন ও কগনিটিভ অন্ধত্ব', NULL, 'ٱللَّهُ يَسْتَهْزِئُ بِهِمْ وَيَمُدُّهُمْ فِى طُغْيَـٰنِهِمْ — ডিলেড ফিডব্যাক লুপ ও ফলস স্ট্যাবিলিটি: সিস্টেমিক নিয়মে তাদের বিচ্যুতি লুপে দীর্ঘ সময় ছেড়ে দিয়ে অন্ধ বিভ্রান্তিতে ফেলে দেওয়া।', 'https://everyayah.com/data/Alafasy_128kbps/002015.mp3', now()),
  (2, 16, '', '[{"id":18658,"position":1,"text_uthmani":"أُو۟لَـٰٓئِكَ","transliteration":"ulāika","translation_bn":"তারাই (ঐসব লোক)","root":"—","lemma":"أُولَٰ^ئِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":18659,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":18660,"position":3,"text_uthmani":"ٱشْتَرَوُا۟","transliteration":"ish''tarawū","translation_bn":"কিনেছে","root":"شري","lemma":"ٱشْتَرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18661,"position":4,"text_uthmani":"ٱلضَّلَـٰلَةَ","transliteration":"l-ḍalālata","translation_bn":"পথভ্রশ্ততা","root":"ضلل","lemma":"ضَلَٰلَة","grammar_bn":"শব্দ"},{"id":18662,"position":5,"text_uthmani":"بِٱلْهُدَىٰ","transliteration":"bil-hudā","translation_bn":"সৎপথের বিনিময়","root":"هدي","lemma":"هُدًى","grammar_bn":"অব্যয় (Preposition)"},{"id":18663,"position":6,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"সুতরাং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":18664,"position":7,"text_uthmani":"رَبِحَت","transliteration":"rabiḥat","translation_bn":"লাভজনক হয়","root":"ربح","lemma":"رَبِحَت","grammar_bn":"ক্রিয়া (Verb)"},{"id":18665,"position":8,"text_uthmani":"تِّجَـٰرَتُهُمْ","transliteration":"tijāratuhum","translation_bn":"তাদের ব্যবসা","root":"تجر","lemma":"تِجَٰرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":18666,"position":9,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18667,"position":10,"text_uthmani":"كَانُوا۟","transliteration":"kānū","translation_bn":"তারা ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18668,"position":11,"text_uthmani":"مُهْتَدِينَ","transliteration":"muh''tadīna","translation_bn":"সৎপথে পরিচালিত","root":"هدي","lemma":"مُّهْتَدُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":18669,"position":12,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'ulāika alladhīna ish''tarawū l-ḍalālata bil-hudā famā rabiḥat tijāratuhum wamā kānū muh''tadīna', 'তারাই হিদায়াতের বিনিময়ে গোমরাহী ক্রয় করেছে, কিন্তু তাতে তাদের ব্যবসা লাভজনক হয়নি, আর তারা সৎপথপ্রাপ্তও নয়।', 'Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.', 'তারাই হিদায়াতের বিনিময়ে গোমরাহী ক্রয় করেছে, কিন্তু তাতে তাদের ব্যবসা লাভজনক হয়নি, আর তারা সৎপথপ্রাপ্তও নয়।', 'Those are the ones who have purchased error [in exchange] for guidance, so their transaction has brought no profit, nor were they guided.', 'তারাই হলো সেই ট্র্যাশ নোড—যারা অপ্টিমাল কসমিক ট্র্যাক ও গাইডবুকের (আল-হুদা) পরিবর্তে সিস্টেমের ডেটা-ক্রাশ বা চরম বিভ্রান্তিকে (আদ-দালালাহ) নিজেদের ওএসে এক্সচেঞ্জ বা ইনপুট (Buy) করেছে; ফলে তাদের এই কগনিটিভ ট্রেডিং বা ডাটা-এক্সচেঞ্জ (তিজারাতুহুম) সিস্টেমে কোনো পজিটিভ আউটপুট বা গেইন দিতে পারেনি এবং তারা সঠিক ফ্রিকোয়েন্সির ভেক্টরে (মুহতাদিন) সচল থাকতে সম্পূর্ণ ব্যর্থ হলো।', NULL, 'কগনিটিভ ট্রেডিং লস ও ডাটা-ক্র্যাশ চয়েস', NULL, 'ٱشْتَرَوُا۟ ٱلضَّلَـٰلَةَ بِٱلْهُدَىٰ — নেগেটিভ ভ্যালু ট্রানজ্যাকশন: সত্য গাইডেন্সের বিনিময়ে ধ্বংসাত্মক বিচ্যুতি কিনে নিয়ে লাইফ-সাইকেল সম্পূর্ণরূপে দেউলিয়া করে ফেলা।', 'https://everyayah.com/data/Alafasy_128kbps/002016.mp3', now()),
  (2, 17, '', '[{"id":19766,"position":1,"text_uthmani":"مَثَلُهُمْ","transliteration":"mathaluhum","translation_bn":"তাদের উপমা","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":19767,"position":2,"text_uthmani":"كَمَثَلِ","transliteration":"kamathali","translation_bn":"উপমা যেমন (এক ব্যক্তির)","root":"مثل","lemma":"مَثَل","grammar_bn":"অব্যয় (Preposition)"},{"id":19768,"position":3,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19769,"position":4,"text_uthmani":"ٱسْتَوْقَدَ","transliteration":"is''tawqada","translation_bn":"জ্বালালো","root":"وقد","lemma":"ٱسْتَوْقَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19770,"position":5,"text_uthmani":"نَارًۭا","transliteration":"nāran","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":19771,"position":6,"text_uthmani":"فَلَمَّآ","transliteration":"falammā","translation_bn":"অতঃপর যখন","root":"—","lemma":"لَمَّا\r","grammar_bn":"শব্দ"},{"id":19772,"position":7,"text_uthmani":"أَضَآءَتْ","transliteration":"aḍāat","translation_bn":"আলোকিত করলো","root":"ضوا","lemma":"أَضَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19773,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":19774,"position":9,"text_uthmani":"حَوْلَهُۥ","transliteration":"ḥawlahu","translation_bn":"তার চারপাশে","root":"حول","lemma":"حَوْل","grammar_bn":"স্থানবাচক (Location)"},{"id":19775,"position":10,"text_uthmani":"ذَهَبَ","transliteration":"dhahaba","translation_bn":"নিলেন","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19776,"position":11,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":19777,"position":12,"text_uthmani":"بِنُورِهِمْ","transliteration":"binūrihim","translation_bn":"তাদের আলো নিয়ে","root":"نور","lemma":"نُور","grammar_bn":"অব্যয় (Preposition)"},{"id":19778,"position":13,"text_uthmani":"وَتَرَكَهُمْ","transliteration":"watarakahum","translation_bn":"এবং তাদের ছেড়ে দিলেন","root":"ترك","lemma":"تَرَكَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19779,"position":14,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19780,"position":15,"text_uthmani":"ظُلُمَـٰتٍۢ","transliteration":"ẓulumātin","translation_bn":"অন্ধকার সমূহের","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":19781,"position":16,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":19782,"position":17,"text_uthmani":"يُبْصِرُونَ","transliteration":"yub''ṣirūna","translation_bn":"তারা দেখতে পায়","root":"بصر","lemma":"أَبْصَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19783,"position":18,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'mathaluhum kamathali alladhī is''tawqada nāran falammā aḍāat mā ḥawlahu dhahaba l-lahu binūrihim watarakahum fī ẓulumātin lā yub''ṣirūna', 'তাদের উদাহরণ, যেমন এক ব্যক্তি আগুন জ্বালালো, তা যখন তার চারদিক আলোকিত করল আল্লাহ তখন তাদের জ্যোতি অপসারণ করে দিলেন এবং তাদেরকে এমন ঘন অন্ধকারে ফেলে দিলেন যে, তারা কিছুই দেখতে পায় না।', 'Their example is that of one who kindled a fire, but when it illuminated what was around him, Allah took away their light and left them in darkness [so] they could not see.', 'তাদের উদাহরণ, যেমন এক ব্যক্তি আগুন জ্বালালো, তা যখন তার চারদিক আলোকিত করল আল্লাহ তখন তাদের জ্যোতি অপসারণ করে দিলেন এবং তাদেরকে এমন ঘন অন্ধকারে ফেলে দিলেন যে, তারা কিছুই দেখতে পায় না।', 'Their example is that of one who kindled a fire, but when it illuminated what was around him, Allah took away their light and left them in darkness [so] they could not see.', 'তাদের সিস্টেমিক মেকানিজমটি ঠিক এমন একটি এনভায়রনমেন্টের মতো—যেখানে কেউ একটি সাময়িক তাপীয় শক্তির উৎস বা আলো (নার) প্রজ্বলন করল; অতঃপর যখন সেই আলো তার চারপাশের ডাটা-প্যারামিটারকে দৃশ্যমান (আদআত) করল, ঠিক তখনই মহাজাগতিক বায়ো-ইলেক্ট্রিক্যাল নিয়মের ডিফল্ট কোডে (আল্লাহ) তাদের অভ্যন্তরীণ রিসিভিং ফোটন বা প্রকৃত গাইডেন্স-আলো (নূর) বিলুপ্ত হয়ে গেল এবং সিস্টেম তাদেরকে এমন এক গভীর ডাটা-ডার্কনেস বা ব্ল্যাকআউটের (জুলুমাত) মধ্যে ফেলে দিল যেখানে তাদের ভিজ্যুয়াল সেন্সরগুলো সম্পূর্ণ অকেজো (লা ইয়ুবসিরুন) হয়ে পড়ে;', NULL, 'লাইট সিমুলেশন ও ফোটন রিসিভিং ফেইলিওর', NULL, 'যাহাবাল্লাহু বিনুরিহিম (ذَهَبَ اللَّهُ بِنُورِهِمْ - ফোটন রিসিভিং ফেইলিওর): ১৭ নম্বর আয়াতে একটি গভীর অপটিক্যাল মেকানিজম রয়েছে। ''নার'' হলো বাহ্যিক আগুন বা স্থূল আলো, যা কাফের-মুনাফিকরা দুনিয়াবি জ্ঞান বা চাতুর্য দিয়ে তৈরি করে। কিন্তু ''নূর'' হলো ভেতরের চেতনা বা ইলেক্ট্রোম্যাগনেটিক পিউরিটি যা সত্যকে প্রসেস করে। তারা সাময়িক আলো পেলেও তাদের হার্ডওয়্যারের অভ্যন্তরীণ নিউরাল রিসিভারটি (নূর) নষ্ট হয়ে যায়। ফলে বাহ্যিক আলো থাকা সত্ত্বেও ভেতরে চরম মনস্তাত্ত্বিক অন্ধকার বা "ব্ল্যাকআউট" তৈরি হয়।', 'https://everyayah.com/data/Alafasy_128kbps/002017.mp3', now()),
  (2, 18, '', '[{"id":20856,"position":1,"text_uthmani":"صُمٌّۢ","transliteration":"ṣummun","translation_bn":"বধির","root":"صمم","lemma":"أَصَمّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20857,"position":2,"text_uthmani":"بُكْمٌ","transliteration":"buk''mun","translation_bn":"বোবা","root":"بكم","lemma":"أَبْكَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":20858,"position":3,"text_uthmani":"عُمْىٌۭ","transliteration":"ʿum''yun","translation_bn":"অন্ধ","root":"عمي","lemma":"أَعْمَىٰ","grammar_bn":"বিশেষ্য (Noun)"},{"id":20859,"position":4,"text_uthmani":"فَهُمْ","transliteration":"fahum","translation_bn":"সুতরাং তারা","root":"—","lemma":"فَهُمْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20860,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":20861,"position":6,"text_uthmani":"يَرْجِعُونَ","transliteration":"yarjiʿūna","translation_bn":"প্রত্যাবর্তন করবে","root":"رجع","lemma":"رَجَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20862,"position":7,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'ṣummun buk''mun ʿum''yun fahum lā yarjiʿūna', 'তারা বধির, মূক, অন্ধ; কাজেই তারা (হিদায়াতের দিকে) ফিরে আসবে না।', 'Deaf, dumb and blind - so they will not return [to the right path].', 'তারা বধির, মূক, অন্ধ; কাজেই তারা (হিদায়াতের দিকে) ফিরে আসবে না।', 'Deaf, dumb and blind - so they will not return [to the right path].', 'তারা তথ্যগতভাবে সম্পূর্ণ বধির (অডিও ইনপুট লকড), বোবা (ডাটা আউটপুট বা সত্য প্রকাশে অক্ষম) এবং কগনিটিভলি অন্ধ (ভিজ্যুয়াল সেন্সর ব্লকড); যার ফলে তারা আর কখনোই ডিফল্ট অপ্টিমাল সিস্টেম ট্র্যাকে রি-অ্যালাইন বা ফিরে (লা ইয়ারজিউন) আসতে পারবে না।', NULL, 'সেন্সর ব্লকিং ও নোড আইসোলেশন', NULL, 'صُمٌّۢ بُكْمٌ عُمْىٌۭ فَهُمْ لَا يَرْجِعُونَ — কমপ্লিট সেন্সরি ব্লকেজ ও নো-রিকভারি স্টেট: ইনপুট ও আউটপুট চ্যানেল সম্পূর্ণ বন্ধ হয়ে যাওয়ায় ওওএসে ডিফল্ট মোডে ফিরে আসার ক্ষমতা হারানো।', 'https://everyayah.com/data/Alafasy_128kbps/002018.mp3', now()),
  (2, 19, '', '[{"id":22027,"position":1,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22028,"position":2,"text_uthmani":"كَصَيِّبٍۢ","transliteration":"kaṣayyibin","translation_bn":"মতো বৃষ্টিপাতের","root":"صوب","lemma":"صَيِّب","grammar_bn":"অব্যয় (Preposition)"},{"id":22029,"position":3,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22030,"position":4,"text_uthmani":"ٱلسَّمَآءِ","transliteration":"l-samāi","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":22031,"position":5,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"তার মধ্যে (আছে)","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22032,"position":6,"text_uthmani":"ظُلُمَـٰتٌۭ","transliteration":"ẓulumātun","translation_bn":"অন্ধকার","root":"ظلم","lemma":"ظُلُمَٰت","grammar_bn":"বিশেষ্য (Noun)"},{"id":22033,"position":7,"text_uthmani":"وَرَعْدٌۭ","transliteration":"waraʿdun","translation_bn":"এবং গর্জন","root":"رعد","lemma":"رَعْد","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22034,"position":8,"text_uthmani":"وَبَرْقٌۭ","transliteration":"wabarqun","translation_bn":"ও বিদ্যুৎচমক","root":"برق","lemma":"بَرْق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":22035,"position":9,"text_uthmani":"يَجْعَلُونَ","transliteration":"yajʿalūna","translation_bn":"তারা রাখে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22036,"position":10,"text_uthmani":"أَصَـٰبِعَهُمْ","transliteration":"aṣābiʿahum","translation_bn":"তাদের আঙ্গুলগুলোকে","root":"صبع","lemma":"أَصَٰبِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":22037,"position":11,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22038,"position":12,"text_uthmani":"ءَاذَانِهِم","transliteration":"ādhānihim","translation_bn":"তাদের কানগুলোর","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":22039,"position":13,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"কারনে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":22040,"position":14,"text_uthmani":"ٱلصَّوَٰعِقِ","transliteration":"l-ṣawāʿiqi","translation_bn":"বজ্রধ্বনির","root":"صعق","lemma":"صَاعِقَة","grammar_bn":"শব্দ"},{"id":22041,"position":15,"text_uthmani":"حَذَرَ","transliteration":"ḥadhara","translation_bn":"ভয়ে","root":"حذر","lemma":"حَذَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":22042,"position":16,"text_uthmani":"ٱلْمَوْتِ ۚ","transliteration":"l-mawti","translation_bn":"মৃত্যুর","root":"موت","lemma":"مَوْت","grammar_bn":"শব্দ"},{"id":22044,"position":17,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"অথচ আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":22045,"position":18,"text_uthmani":"مُحِيطٌۢ","transliteration":"muḥīṭun","translation_bn":"পরিবেষ্টনকারী","root":"حوط","lemma":"مُحِيط","grammar_bn":"বিশেষ্য (Noun)"},{"id":22046,"position":19,"text_uthmani":"بِٱلْكَـٰفِرِينَ","transliteration":"bil-kāfirīna","translation_bn":"কাফিরদের","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":22047,"position":20,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'aw kaṣayyibin mina l-samāi fīhi ẓulumātun waraʿdun wabarqun yajʿalūna aṣābiʿahum fī ādhānihim mina l-ṣawāʿiqi ḥadhara l-mawti wal-lahu muḥīṭun bil-kāfirīna', 'অথবা যেমন আকাশের বর্ষণমুখর মেঘ, যাতে আছে গাঢ় অন্ধকার, বজ্রধ্বনি ও বিদ্যুৎ চমক, বজ্রধ্বনিতে মৃত্যু ভয়ে তারা তাদের কানে আঙ্গুল ঢুকিয়ে দেয়। আল্লাহ কাফেরদেরকে পরিবেষ্টন করে আছেন।', 'Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allah is encompassing of the disbelievers.', 'অথবা যেমন আকাশের বর্ষণমুখর মেঘ, যাতে আছে গাঢ় অন্ধকার, বজ্রধ্বনি ও বিদ্যুৎ চমক, বজ্রধ্বনিতে মৃত্যু ভয়ে তারা তাদের কানে আঙ্গুল ঢুকিয়ে দেয়। আল্লাহ কাফেরদেরকে পরিবেষ্টন করে আছেন।', 'Or [it is] like a rainstorm from the sky within which is darkness, thunder and lightning. They put their fingers in their ears against the thunderclaps in dread of death. But Allah is encompassing of the disbelievers.', 'অথবা তাদের অবস্থা হাই-অ্যাল্টিচিউড বায়ুমণ্ডল (সামা) থেকে ধেয়ে আসা তীব্র মাস-এনার্জি ইনফ্লাক্স বা কসমিক স্টর্মের (সাইয়্যিব) মতো—যার ভেতরে রয়েছে গভীর আণবিক অন্ধকার (জুলুমাত), তীব্র অ্যাকোস্টিক ওয়েভ বা মেকানিক্যাল শকওয়েভ (রাদ) এবং আল্ট্রা-ভায়োলেট ইলেক্ট্রোম্যাগনেটিক ফ্ল্যাশ বা বিদ্যুৎচমক (বার্ক); এই আকস্মিক কসমিক এনার্জি ডিসচার্জের (সাওয়াnum) ফলে সৃষ্ট ধ্বংসাত্মক প্রতিক্রিয়া ও সিস্টেম-ডেথ (আল-মাওত)-এর ভয়ে তারা তাদের অডিও ইনপুট চ্যানেলগুলো আইসোলেট বা বন্ধ করে দেয়; অথচ মহাজাগতিক সোর্স কোড (আল্লাহ) তাঁর সুনির্দিষ্ট ফিজিক্যাল ও কোয়ান্টাম ফিল্ডের মাধ্যমে এই সত্য প্রত্যাখ্যানকারী আউটলায়ারদের (কাফিরিন) চারদিক থেকে সম্পূর্ণ এনক্যাপসুলেট বা পরিবেষ্টন (মুহিত্ব) করে রেখেছেন।', NULL, 'কসমিক স্টর্ম, হাই-ভোল্টেজ ডিসচার্জ ও কোয়ান্টাম এনক্যাপসুলেশন', NULL, 'রাদ, বার্ক, সাওয়াnum (رَعْدٌ وَبَرْقٌ... الصَّوَاعِقِ - কসমিক স্টর্ম ও হাই-ভোল্টেজ ডিসচার্জ): ১৯ নম্বর আয়াতে আল্লাহ মক-সিমুলেশন ব্যবহার করেছেন। আকাশ থেকে যখন কোনো তীব্র ঝড় আসে, তার সাথে যে বিদ্যুৎ চমকায় (বার্ক) এবং শব্দ তৈরি হয় (রাদ), তা হলো এক বিশাল এনার্জি ডিসচার্জ। মুনাফিকরা যখন কুরআনের এই তীব্র সত্যের এনার্জি ফিল্ডের মুখোমুখি হয়, তখন তাদের ভেতরের মিথ্যার সিস্টেমটি কাঁপতে শুরু করে। তারা এই হাই-ফ্রিকোয়েন্সি ডাটা ইনপুট নিতে ভয় পায় (কানে আঙুল দেয়) কারণ এই ডাটা প্রসেস করতে গেলে তাদের নিজেদের স্বার্থ ও অহংকারের সিস্টেমটির মৃত্যু (সিস্টেম-ডেথ) ঘটবে।
